blocks.mermaid:
flowchart TD
  A["¿Cuándo pasa algo?"] --> B{"¿Es un día de la semana?"}
  B -- "Sí" --> C["on + día: on Monday = el lunes"]
  B -- "No" --> D{"¿Es un mes?"}
  D -- "Sí" --> E["in + mes: in July = en julio"]
  D -- "No: hoy o mañana" --> F["sin preposición: today, tomorrow"]

flowchart TD
  A["¿Cuál es el sujeto?"] --> B{"¿Es I?"}
  B -- "Sí" --> C["be → am · have → have · otros → base: I go"]
  B -- "No" --> D{"¿Es he, she, it o un sustantivo singular?"}
  D -- "Sí" --> E["be → is · have → has · otros → base + s: she goes"]
  D -- "No: you, we, they o un plural" --> F["be → are · have → have · otros → base: they go"]

flowchart TD
  A["Sujeto: he, she, it o un sustantivo singular"] --> B{"¿El verbo es be o have?"}
  B -- "be" --> C["is: he is"]
  B -- "have" --> D["has: she has"]
  B -- "Otro verbo" --> E{"¿Termina en o, s, sh, ch, x o z?"}
  E -- "Sí" --> F["+ es: goes, does, washes"]
  E -- "No" --> G{"¿Termina en consonante + y?"}
  G -- "Sí" --> H["y → ies: cry → cries"]
  G -- "No" --> I["+ s: puts, takes, says, sees"]

flowchart LR
  A["Último SONIDO del verbo"] --> B{"¿s, z, sh, ch o j?"}
  B -- "Sí" --> C["/ɪz/ · washes, dances"]
  B -- "No" --> D{"¿p, t, k o f?"}
  D -- "Sí" --> E["/s/ · puts, takes, keeps"]
  D -- "No: vocal o sonido sonoro" --> F["/z/ · sees, gives, comes"]

flowchart TD
  A["Verbo base"] --> B{"¿Termina en una e que no suena?"}
  B -- "Sí: come, make, take" --> C["quita la e + ing: coming, making, taking"]
  B -- "No" --> D{"¿Termina en UNA vocal corta + UNA consonante?"}
  D -- "Sí: get, let, put" --> E["dobla la consonante + ing: getting, letting, putting"]
  D -- "No: go, see, keep" --> F["+ ing: going, seeing, keeping"]
